package com.library;

import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import java.sql.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="MYSQL_TEST_URL",matches=".+")
public class CatalogIdentityMigrationTest {
    @Test void v12ToV13PreservesAllOriginalColumnsAndOnlyAddsZeroTechnicalVersionsAndNineEmptyTables()throws Exception{
        String original=System.getenv("MYSQL_TEST_URL"),user=System.getenv().getOrDefault("MYSQL_TEST_USER","root"),pass=System.getenv("MYSQL_TEST_PASSWORD");if(original==null||!original.matches("jdbc:mysql://[^/]+/library_repair_tests(?:\\?.*)?"))throw new IllegalStateException("Disposable schema only");String schema="library_repair_tests_b35_"+UUID.randomUUID().toString().replace("-",""),url=original.replace("/library_repair_tests","/"+schema);
        try(Connection c=DriverManager.getConnection(original,user,pass);Statement s=c.createStatement()){s.execute("CREATE DATABASE `"+schema+"` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci");}
        try{Flyway.configure().dataSource(url,user,pass).locations("classpath:db/migration").target("12").load().migrate();JdbcTemplate j=new JdbcTemplate(new DriverManagerDataSource(url,user,pass));j.update("INSERT INTO publisher(id,name,address) VALUES (89001,'合成旧出版社','合成联络资料保值')");j.update("INSERT INTO book_category(id,name) VALUES (89001,'绘本迁入合成原分类')");j.update("INSERT INTO book(id,isbn,title,publisher,category_id,stock_total,stock_available) VALUES (89001,'B35-MIGRATION','合成原书名','合成原出版社',89001,1,1)");j.update("INSERT INTO book_copy(id,book_id,barcode,action_version) VALUES (89001,89001,'000B35Aa ',7)");j.update("INSERT INTO catalog_book_attribute(book_id,revision,display_title_override,display_origin,age_known,age_origin,updated_at) VALUES (89001,2,'合成展示名','MANUAL',1,'MANUAL','2026-01-01')");j.update("INSERT INTO catalog_book_age_label(book_id,label_code) VALUES (89001,'AGE_0_2')");j.update("INSERT INTO catalog_attribute_request(id,operation_key,actor_id,mode,input_hash,request_json,preview_json,preview_digest,state,created_at,expires_at,receipt_json,committed_at) VALUES (89001,X'423335',89001,'MANUAL',?,'{\"bookId\":89001}','{\"frozen\":true}',?,'COMMITTED','2026-01-01','2026-01-02','{\"frozen\":null}','2026-01-01')","a".repeat(64),"b".repeat(64));j.update("INSERT INTO catalog_attribute_event(book_id,request_id,kind,before_revision,after_revision,changed_fields_json,before_json,after_json,actor_id,occurred_at,reason) VALUES (89001,89001,'MANUAL',1,2,'[\"ageLabels\"]','{}','{}',89001,'2026-01-01','合成历史审计')");
            frozenV8(j);Map<String,List<String>> columns=columns(url,user,pass);assertEquals(54,columns.size());Map<String,List<String>> before=values(url,user,pass,columns);Map<String,String> definitions=definitions(url,user,pass);Flyway next=Flyway.configure().dataSource(url,user,pass).locations("classpath:db/migration").target("13").load();assertEquals(1,next.migrate().migrationsExecuted);assertEquals(0,next.migrate().migrationsExecuted);assertEquals(before,values(url,user,pass,columns));Map<String,String> after=definitions(url,user,pass);for(var entry:definitions.entrySet())if(!List.of("book","publisher","book_category").contains(entry.getKey()))assertEquals(entry.getValue(),after.get(entry.getKey()),entry.getKey());assertEquals(63,after.size());for(String table:List.of("catalog_publisher_profile","catalog_publisher_alias","catalog_category_profile","catalog_category_alias","catalog_book_publisher","catalog_book_theme","catalog_identity_request","catalog_identity_candidate","catalog_identity_event"))assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class));for(String table:List.of("book","publisher","book_category"))assertEquals(0,j.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE catalog_identity_revision<>0",Integer.class));System.out.println("B35_MIGRATION oldTables=54 originalCells=preserved unchangedDefinitions=51 technicalVersions=3 zero=true newTables=9 empty=true V12JsonAndLabels=preserved");
        }finally{try(Connection c=DriverManager.getConnection(original,user,pass);Statement s=c.createStatement()){s.execute("DROP DATABASE `"+schema+"`");}}
    }
    void frozenV8(JdbcTemplate j){j.update("INSERT INTO inventory_intake_request(idempotency_key,request_hash,preview_digest,source_type,operator_id,request_json,preview_json,state,expires_at,confirmed_at,receipt_json) VALUES (X'42333538',?,?,'MANUAL',89001,'{\"metadata\":null}','{\"book\":{\"publisher\":\"合成原出版社\"}}','COMMITTED','2026-01-02','2026-01-01','{\"copies\":[],\"frozen\":true}')","c".repeat(64),"d".repeat(64));}
    Map<String,List<String>> columns(String url,String user,String pass)throws Exception{Map<String,List<String>> all=new TreeMap<>();try(Connection c=DriverManager.getConnection(url,user,pass);Statement s=c.createStatement()){List<String> tables=new ArrayList<>();try(ResultSet r=s.executeQuery("SHOW TABLES")){while(r.next())tables.add(r.getString(1));}for(String table:tables){List<String> names=new ArrayList<>();try(ResultSet r=s.executeQuery("SHOW COLUMNS FROM `"+table+"`")){while(r.next())names.add(r.getString(1));}all.put(table,names);}}return all;}
    Map<String,List<String>> values(String url,String user,String pass,Map<String,List<String>> columns)throws Exception{Map<String,List<String>> all=new TreeMap<>();try(Connection c=DriverManager.getConnection(url,user,pass);Statement s=c.createStatement()){for(var table:columns.entrySet()){List<String> rows=new ArrayList<>();String fields=table.getValue().stream().map(x->"`"+x+"`").reduce((a,b)->a+","+b).orElseThrow();try(ResultSet r=s.executeQuery("SELECT "+fields+" FROM `"+table.getKey()+"`"+(table.getKey().equals("flyway_schema_history")?" WHERE version IS NULL OR version<>'13'":""))){while(r.next()){List<String> row=new ArrayList<>();for(int i=1;i<=r.getMetaData().getColumnCount();i++){byte[] value=r.getBytes(i);row.add(value==null?null:Base64.getEncoder().encodeToString(value));}rows.add(row.toString());}}Collections.sort(rows);all.put(table.getKey(),rows);}}return all;}
    Map<String,String> definitions(String url,String user,String pass)throws Exception{Map<String,String> all=new TreeMap<>();try(Connection c=DriverManager.getConnection(url,user,pass);Statement s=c.createStatement()){List<String> tables=new ArrayList<>();try(ResultSet r=s.executeQuery("SHOW TABLES")){while(r.next())tables.add(r.getString(1));}for(String table:tables)try(ResultSet r=s.executeQuery("SHOW CREATE TABLE `"+table+"`")){r.next();all.put(table,r.getString(2));}}return all;}
}
